/*
 * winshim.h - Linux stand-ins for MultiByteToWideChar / WideCharToMultiByte so the Windows
 *             branch of libdsm's smb_utils.c can be compiled and run under ASan (test harness only)
 *
 * Version : 1.0
 * Usage   : included by the file generated by gen_winutils.sh; implementation in winshim.c
 * Notes   : semantics follow the Win32 documentation: size query with a 0 buffer size, return
 *           value = units written, 0 on failure, characters the ANSI code page cannot hold
 *           become '?'. Code page 0 is modelled as Latin-1; 65001 is UTF-8 with surrogates.
 * History : 1.0  first version.
 */
#ifndef WINSHIM_H
#define WINSHIM_H
#include <stddef.h>
#include <stdint.h>
int MultiByteToWideChar(unsigned cp, unsigned long fl, const char *s, int slen, unsigned short *w, int wlen);
int WideCharToMultiByte(unsigned cp, unsigned long fl, const unsigned short *w, int wlen, char *s, int slen,
                        const char *defc, int *used);
#endif
